content.css:
@font-face {
  font-family: "Sora Vizu";
  font-style: normal;
  font-weight: 300 800;
  font-display: block;
  src: url(data:font/woff2;base64,) format("woff2");
}
.smart-filter-fixed {
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  overflow: visible;
  display: flex;
  align-items: flex-start;
  padding: 0;
  position: relative;
  background: transparent !important;
  font-family: var(--sff-font-family, "Segoe UI"), sans-serif;
  font-size: var(--sff-font-size, 11px);
  color: var(--sff-text-color, #fff);
  /* Feature 1: valor escolhido no cabecalho (Campo : Valor) */
  /* Feature 2: modo Caixa de busca */
  /* item selecionado sob o mouse mantém o fundo selecionado (regra abaixo vence) e, por isso, a cor normal do texto */
  /* Revelacao em cascata das opcoes ao abrir o painel */
}
.smart-filter-fixed .sff-trigger {
  width: var(--sff-control-width, 158px);
  height: var(--sff-control-height, 30px);
  box-sizing: border-box;
  border: 1px solid var(--sff-border-color, #3c4551);
  border-radius: var(--sff-radius, 4px);
  background: var(--sff-field-bg, #151f2e);
  color: var(--sff-text-color, #fff);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 0 9px 0 10px;
  font-family: inherit;
  font-size: inherit;
  font-weight: 600;
  line-height: 1;
  outline: none;
  transition: border-color 120ms ease, background-color 120ms ease, box-shadow 120ms ease;
}
.smart-filter-fixed .sff-trigger.open,
.smart-filter-fixed .sff-trigger:hover,
.smart-filter-fixed .sff-trigger.active-filter {
  border-color: var(--sff-active-border-color, #2563eb);
}
.smart-filter-fixed .sff-trigger.active-filter {
  box-shadow: inset 0 0 0 1px var(--sff-active-border-color, #2563eb);
}
.smart-filter-fixed .motion-enabled .sff-trigger {
  transition: border-color 140ms ease, background-color 140ms ease, box-shadow 200ms ease, transform 140ms ease;
}
.smart-filter-fixed .motion-enabled .sff-trigger:hover {
  transform: translateY(-1px);
}
.smart-filter-fixed .sff-trigger:focus-visible {
  box-shadow: inset 0 0 0 2px var(--sff-active-border-color, #2563eb);
}
.smart-filter-fixed .sff-trigger-main {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  flex: 1 1 auto;
}
.smart-filter-fixed .sff-trigger-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: left;
  flex: 1 1 auto;
  line-height: 1.35;
}
.smart-filter-fixed .sff-hierarchy {
  position: relative;
  width: var(--sff-control-width, 520px);
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: var(--sff-hierarchy-gap, 12px);
  box-sizing: border-box;
}
.smart-filter-fixed .sff-hierarchy .sff-trigger {
  width: 100%;
  min-width: 0;
}
.smart-filter-fixed .sff-hierarchy-trigger:disabled {
  cursor: default;
  opacity: 0.5;
}
.smart-filter-fixed .sff-hierarchy-dropdown {
  width: calc((var(--sff-control-width, 520px) - var(--sff-hierarchy-gap, 12px)) / 2);
}
.smart-filter-fixed .sff-hierarchy-dropdown--category {
  left: 0;
}
.smart-filter-fixed .sff-hierarchy-dropdown--subcategory {
  left: calc((var(--sff-control-width, 520px) + var(--sff-hierarchy-gap, 12px)) / 2);
}
.smart-filter-fixed .sff-hierarchy--levels-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.smart-filter-fixed .sff-hierarchy--levels-3 ~ .sff-hierarchy-dropdown {
  width: calc((var(--sff-control-width, 520px) - 2 * var(--sff-hierarchy-gap, 12px)) / 3);
}
.smart-filter-fixed .sff-hierarchy--levels-3 ~ .sff-hierarchy-dropdown--subcategory {
  left: calc((var(--sff-control-width, 520px) + var(--sff-hierarchy-gap, 12px)) / 3);
}
.smart-filter-fixed .sff-hierarchy--levels-3 ~ .sff-hierarchy-dropdown--subcategory2 {
  left: calc(2 * (var(--sff-control-width, 520px) + var(--sff-hierarchy-gap, 12px)) / 3);
}
.smart-filter-fixed .sff-tree-trigger,
.smart-filter-fixed .sff-tree-dropdown {
  width: var(--sff-control-width, 520px);
  max-width: 100%;
}
.smart-filter-fixed .sff-tree-trigger:disabled {
  cursor: default;
  opacity: 0.5;
}
.smart-filter-fixed .sff-tree-dropdown {
  left: 0;
}
.smart-filter-fixed .sff-tree-options {
  padding: 4px;
}
.smart-filter-fixed .sff-tree-route-row {
  width: 100%;
  min-width: 0;
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr);
  align-items: center;
  column-gap: 4px;
  box-sizing: border-box;
}
.smart-filter-fixed .sff-tree-toggle,
.smart-filter-fixed .sff-tree-toggle-spacer {
  width: 22px;
  height: 22px;
  box-sizing: border-box;
}
.smart-filter-fixed .sff-tree-toggle {
  border: 1px solid var(--sff-border-color, #3c4551);
  border-radius: var(--sff-checkbox-radius, 4px);
  background: transparent;
  color: var(--sff-active-border-color, #2563eb);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  font-family: inherit;
  font-size: 16px;
  font-weight: 700;
  line-height: 1;
  outline: none;
}
.smart-filter-fixed .sff-tree-toggle:hover:not(:disabled) {
  background: var(--sff-hover-bg, #f2f6fd);
  border-color: var(--sff-active-border-color, #2563eb);
  color: var(--sff-hover-text, var(--sff-text-color, #fff));
}
.smart-filter-fixed .sff-tree-toggle:focus-visible {
  box-shadow: 0 0 0 2px var(--sff-focus-ring, rgba(37, 99, 235, 0.4));
}
.smart-filter-fixed .sff-tree-toggle:disabled {
  cursor: default;
  opacity: 0.55;
}
.smart-filter-fixed .sff-tree-toggle:not(.sff-tree-chevron) {
  position: relative;
  justify-self: center;
  width: var(--sff-checkbox-size, 18px);
  height: var(--sff-checkbox-size, 18px);
  font-size: 0;
}
.smart-filter-fixed .sff-tree-toggle:not(.sff-tree-chevron)::before,
.smart-filter-fixed .sff-tree-toggle:not(.sff-tree-chevron)::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 8px;
  height: 2px;
  margin: -1px 0 0 -4px;
  border-radius: 1px;
  background: currentColor;
}
.smart-filter-fixed .sff-tree-toggle:not(.sff-tree-chevron)::after {
  width: 2px;
  height: 8px;
  margin: -4px 0 0 -1px;
}
.smart-filter-fixed .sff-tree-toggle:not(.sff-tree-chevron)[aria-expanded="true"]::after {
  display: none;
}
.smart-filter-fixed .sff-tree-option {
  min-width: 0;
}
.smart-filter-fixed .sff-tree-child-group {
  width: 100%;
  box-sizing: border-box;
}
.smart-filter-fixed .sff-tree-child-group[hidden] {
  display: none;
}
.smart-filter-fixed .sff-tree-child-option {
  width: calc(100% - 28px);
  margin-left: 28px;
  padding-left: 14px;
  position: relative;
}
.smart-filter-fixed .sff-tree-child-option::before {
  content: none;
  display: none;
}
.smart-filter-fixed .sff-tree-route-row--nested {
  padding-left: 28px;
}
.smart-filter-fixed .sff-tree-child-option--deep {
  width: calc(100% - 56px);
  margin-left: 56px;
}
.smart-filter-fixed.sff-tree-cabecalho .sff-tree-child-option::before {
  display: none;
}
.smart-filter-fixed.sff-tree-cabecalho .sff-tree-child-option {
  padding-left: 6px;
}
.smart-filter-fixed.sff-tree-cabecalho .sff-tree-child-option--deep {
  width: calc(100% - 84px);
  margin-left: 84px;
}
.smart-filter-fixed.sff-tree-cabecalho .sff-checkbox.partial::after {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 1px;
  background: var(--sff-checkbox-color, #2563eb);
}
.smart-filter-fixed.sff-tree-cabecalho .sff-checkbox.partial .sff-check-svg {
  display: none;
}
.smart-filter-fixed .sff-option.sff-tree-child-option {
  width: calc(100% - 28px);
}
.smart-filter-fixed .sff-option.sff-tree-child-option--deep {
  width: calc(100% - 56px);
}
.smart-filter-fixed.sff-tree-cabecalho .sff-option.sff-tree-child-option--deep {
  width: calc(100% - 84px);
}
.smart-filter-fixed .sff-tree-route-row--funda {
  padding-left: calc((var(--sff-profundidade, 3) - 1) * 28px);
}
.smart-filter-fixed .sff-option.sff-tree-child-option--funda {
  width: calc(100% - (var(--sff-profundidade, 4) - 1) * 28px);
  margin-left: calc((var(--sff-profundidade, 4) - 1) * 28px);
}
.smart-filter-fixed.sff-tree-cabecalho .sff-option.sff-tree-child-option--funda {
  width: calc(100% - var(--sff-profundidade, 4) * 28px);
  margin-left: calc(var(--sff-profundidade, 4) * 28px);
}
.smart-filter-fixed .sff-tree-header .sff-tree-header-option .sff-label {
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 0.9em;
  font-weight: 600;
}
.smart-filter-fixed .sff-tree-header .sff-tree-header-option {
  cursor: pointer;
}
.smart-filter-fixed .sff-tree-badge {
  flex: 0 0 auto;
  margin-left: auto;
  padding: 0 8px;
  height: 22px;
  line-height: 22px;
  border-radius: 11px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
  background: var(--sff-counter-bg, #fff);
  color: var(--sff-counter-fg, #0a0a0b);
}
.smart-filter-fixed .sff-tree-toggle.sff-tree-chevron {
  border: 0;
  background: transparent;
  color: var(--sff-text-color, #fff);
}
.smart-filter-fixed .sff-tree-toggle.sff-tree-chevron svg {
  width: 14px;
  height: 14px;
  transform: rotate(-90deg);
  transition: transform 0.15s ease;
}
.smart-filter-fixed .sff-tree-toggle.sff-tree-chevron.open svg {
  transform: rotate(0deg);
}
.smart-filter-fixed .sff-tree-toggle.sff-tree-chevron:hover:not(:disabled) {
  background: transparent;
  border-color: transparent;
  color: var(--sff-text-color, #fff);
}
.smart-filter-fixed .sff-count-badge {
  flex: 0 0 auto;
  padding: 1px 6px;
  box-sizing: border-box;
  font-size: 0.92em;
  font-weight: 700;
  line-height: 1.25;
  text-align: center;
  border-radius: var(--sff-counter-radius, 4px);
  background: var(--sff-counter-bg, #59b7c8);
  color: var(--sff-counter-fg, #fff);
}
.smart-filter-fixed .sff-trigger-arrow {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  opacity: 0.7;
  color: var(--sff-text-color, #0f1e3d);
}
.smart-filter-fixed .sff-chevron-svg {
  display: block;
  transform: rotate(0deg);
}
.smart-filter-fixed .motion-enabled .sff-chevron-svg {
  transition: transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.smart-filter-fixed .sff-trigger.open .sff-chevron-svg {
  transform: rotate(180deg);
}
.smart-filter-fixed .motion-enabled .sff-count-badge {
  animation: sff-badge-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
.smart-filter-fixed .sff-trigger-field {
  opacity: 0.66;
}
.smart-filter-fixed .sff-trigger-value {
  font-weight: 700;
  color: var(--sff-active-border-color, #2563eb);
}
.smart-filter-fixed .sff-searchbox-wrap {
  position: relative;
  width: var(--sff-control-width, 158px);
  height: var(--sff-control-height, 30px);
  box-sizing: border-box;
}
.smart-filter-fixed .sff-searchbox {
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  border: 1px solid var(--sff-border-color, #3c4551);
  border-radius: var(--sff-radius, 4px);
  background: var(--sff-field-bg, #151f2e);
  color: var(--sff-text-color, #fff);
  font-family: inherit;
  font-size: inherit;
  font-weight: 600;
  line-height: 1;
  outline: none;
  padding: 0 28px 0 30px;
  transition: border-color 120ms ease, box-shadow 160ms ease;
}
.smart-filter-fixed .sff-searchbox::placeholder {
  color: var(--sff-text-color, #5b6b86);
  opacity: 0.5;
  font-weight: 500;
}
.smart-filter-fixed .sff-searchbox:hover {
  border-color: var(--sff-active-border-color, #2563eb);
}
.smart-filter-fixed .sff-searchbox-wrap.active-filter .sff-searchbox {
  border-color: var(--sff-active-border-color, #2563eb);
  box-shadow: 0 0 0 3px var(--sff-accent-glow, rgba(37, 99, 235, 0.16));
}
.smart-filter-fixed .sff-searchbox:focus {
  border-color: var(--sff-active-border-color, #2563eb);
  box-shadow: 0 0 0 3px var(--sff-focus-ring, rgba(37, 99, 235, 0.4));
}
.smart-filter-fixed .sff-searchbox-icon {
  position: absolute;
  left: 9px;
  top: 50%;
  transform: translateY(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--sff-text-color, #5b6b86);
  opacity: 0.55;
  pointer-events: none;
}
.smart-filter-fixed .sff-searchbox-wrap.active-filter .sff-searchbox-icon {
  color: var(--sff-active-border-color, #2563eb);
  opacity: 0.9;
}
.smart-filter-fixed .sff-search-svg {
  display: block;
}
.smart-filter-fixed .sff-searchbox-clear {
  position: absolute;
  right: 6px;
  top: 50%;
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--sff-clear-color, #db6a5e);
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  outline: none;
}
.smart-filter-fixed .sff-searchbox-clear:hover {
  background: var(--sff-hover-bg, #f2f6fd);
  color: var(--sff-hover-text, var(--sff-text-color, #fff));
}
.smart-filter-fixed .sff-date-trigger-text {
  padding-right: 6px;
}
.smart-filter-fixed .sff-date-panel {
  position: absolute;
  top: calc(var(--sff-control-height, 34px) + var(--sff-gap, 6px));
  left: 0;
  z-index: 999;
  width: var(--sff-dropdown-width, var(--sff-control-width, 158px));
  max-width: 100%;
  min-width: 0;
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  column-gap: var(--sff-calendar-gap, 12px);
  box-sizing: border-box;
  padding: 10px;
  border: 1px solid var(--sff-border-color, #e8eef7);
  border-radius: var(--sff-radius, 10px);
  background: var(--sff-dropdown-bg, #fff);
  color: var(--sff-text-color, #0f1e3d);
}
.smart-filter-fixed .sff-date-fields {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  flex: 0 0 auto;
  width: var(--sff-date-field-width, 190px);
  min-width: 0;
  row-gap: var(--sff-date-field-gap, 10px);
}
.smart-filter-fixed .sff-date-fields .sff-date-separator {
  display: none;
}
.smart-filter-fixed.shadow-enabled .sff-date-panel {
  box-shadow: 0 16px 40px rgba(15, 30, 61, 0.16), 0 2px 8px rgba(15, 30, 61, 0.08);
}
.smart-filter-fixed .motion-enabled .sff-date-panel {
  transform-origin: top left;
  animation: sff-dropdown-in 0.2s cubic-bezier(0.2, 0.85, 0.25, 1) both;
}
.smart-filter-fixed .sff-date-field {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
  width: 100%;
  flex: 0 0 auto;
  height: var(--sff-date-field-height, var(--sff-control-height, 34px));
  box-sizing: border-box;
}
.smart-filter-fixed .sff-date-field--from,
.smart-filter-fixed .sff-date-field--to {
  flex: 0 0 auto;
}
.smart-filter-fixed .sff-date-label {
  position: static;
  z-index: 1;
  margin: 0 0 4px 3px;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--sff-text-color, #0f1e3d);
  font-size: 0.68em;
  font-weight: 700;
  line-height: 1;
  opacity: 0.62;
  pointer-events: none;
}
.smart-filter-fixed .sff-date-input {
  width: 100%;
  min-width: 0;
  flex: 1 1 auto;
  min-height: 0;
  box-sizing: border-box;
  border: 1px solid var(--sff-border-color, #e8eef7);
  border-radius: var(--sff-radius, 10px);
  background: var(--sff-field-bg, #fff);
  color: var(--sff-text-color, #0f1e3d);
  font-family: inherit;
  font-size: 0.94em;
  font-weight: 650;
  line-height: normal;
  outline: none;
  padding: 0 12px 0 42px;
  transition: border-color 140ms ease, box-shadow 180ms ease, transform 140ms ease;
}
.smart-filter-fixed.calendar-theme-auto .sff-date-input {
  color-scheme: light dark;
}
.smart-filter-fixed.calendar-theme-light .sff-date-input {
  color-scheme: light;
}
.smart-filter-fixed.calendar-theme-dark .sff-date-input {
  color-scheme: dark;
}
.smart-filter-fixed .sff-date-input:hover {
  border-color: var(--sff-active-border-color, #2563eb);
}
.smart-filter-fixed .sff-date-input:focus-visible,
.smart-filter-fixed .sff-date-panel.active-filter .sff-date-input {
  border-color: var(--sff-active-border-color, #2563eb);
  box-shadow: 0 0 0 2px var(--sff-accent-glow, rgba(37, 99, 235, 0.16));
}
.smart-filter-fixed .motion-enabled .sff-date-input:hover {
  transform: translateY(-1px);
}
.smart-filter-fixed .sff-date-input::-webkit-calendar-picker-indicator {
  width: 13px;
  height: 13px;
  margin: 0;
  padding: 0;
  cursor: pointer;
  opacity: 0;
  pointer-events: none;
}
.smart-filter-fixed .sff-calendar-button {
  position: absolute;
  z-index: 2;
  left: 10px;
  right: auto;
  bottom: calc((100% - 19px) / 2 - 13px);
  width: 26px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--sff-calendar-icon-color, var(--sff-active-border-color, #2563eb));
  cursor: pointer;
  outline: none;
}
.smart-filter-fixed .sff-calendar-button:hover {
  background: var(--sff-hover-bg, #f2f6fd);
}
.smart-filter-fixed .sff-calendar-button:focus-visible {
  box-shadow: 0 0 0 2px var(--sff-focus-ring, rgba(37, 99, 235, 0.4));
}
.smart-filter-fixed .sff-calendar-svg {
  display: block;
}
.smart-filter-fixed .sff-date-separator {
  display: none;
}
.smart-filter-fixed .sff-date-clear {
  grid-column: 2;
  grid-row: 1 / span 2;
  align-self: center;
  width: 22px;
  height: 22px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--sff-clear-color, #db6a5e);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  font-family: inherit;
  font-size: 16px;
  line-height: 1;
  outline: none;
}
.smart-filter-fixed .sff-date-clear:hover:not(:disabled),
.smart-filter-fixed .sff-date-clear:focus-visible:not(:disabled) {
  background: var(--sff-hover-bg, #f2f6fd);
  box-shadow: 0 0 0 2px var(--sff-focus-ring, rgba(37, 99, 235, 0.4));
}
.smart-filter-fixed .sff-date-clear:disabled {
  cursor: default;
  opacity: 0.24;
}
.smart-filter-fixed .sff-calendar {
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  user-select: none;
}
.smart-filter-fixed .sff-calendar-empty {
  padding: 10px 4px;
  opacity: 0.7;
  font-size: 0.86em;
  text-align: center;
}
.smart-filter-fixed .sff-calendar-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  column-gap: 6px;
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--sff-subtle-line, rgba(15, 30, 61, 0.08));
}
.smart-filter-fixed .sff-calendar-title {
  flex: 1 1 auto;
  text-align: center;
  font-size: 0.88em;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.smart-filter-fixed .sff-calendar-nav {
  flex: 0 0 auto;
  width: 26px;
  height: 26px;
  padding: 0;
  border: 1px solid var(--sff-border-color, #e8eef7);
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-family: inherit;
  font-size: 1em;
  line-height: 1;
  cursor: pointer;
