.smart-filter-fixed.sff-modo-regua .sff-regua.arrastando .sff-regua-botao {
  cursor: grabbing;
}
.smart-filter-fixed.sff-modo-regua .sff-regua.arrastando .sff-regua-botao {
  transition: left 40ms linear;
}
.smart-filter-fixed.sff-modo-regua .sff-regua.arrastando .sff-regua-cheio {
  transition: left 40ms linear, width 40ms linear;
}
.smart-filter-fixed.sff-modo-regua .sff-regua-rotulo {
  position: absolute;
  top: calc(50% + var(--sff-regua-rotulo-desce, 16px));
  transform: translateX(-50%);
  font-size: var(--sff-regua-rotulo-tamanho, 13px);
  line-height: 1.2;
  color: var(--sff-regua-rotulo, var(--sff-text-color, #1C1915));
  white-space: nowrap;
  font-variant-numeric: tabular-nums lining-nums;
  pointer-events: none;
}
@media (prefers-reduced-motion: reduce) {
  .smart-filter-fixed.sff-modo-regua .sff-regua-botao,
  .smart-filter-fixed.sff-modo-regua .sff-regua-cheio,
  .smart-filter-fixed.sff-modo-regua .sff-regua-balao,
  .smart-filter-fixed.sff-modo-regua .sff-regua.arrastando .sff-regua-botao,
  .smart-filter-fixed.sff-modo-regua .sff-regua.arrastando .sff-regua-cheio {
    transition: none;
  }
}
